from multiprocessing import Pool
import math

def factorial(n):
    return math.factorial(n)

if __name__ == '__main__':
    numbers = [10, 15, 20, 25]
    with Pool(4) as pool:
        results = pool.map(factorial, numbers)
    for n, result in zip(numbers, results):
        print(f'{n}! = {result}')
    print(f'Results: {results}')
